(3559547, 497238, 57032, '<td valign="top">A very well-captured expression.</td>', 'A very well-captured expression.', '2007-04-18 13:30:22.000000', NULL, 1),
(3559549, 499246, 63269, '<td valign="top">This looks like it would be really cool! I''m guessing that you are holding a flashlight with your hair over it? Well, here is my two cents. :)<br/> <br/>First of all, it''s out of focus. If you can fix that, and get a focused image, it will get you a much better photo, and thus a much better score with the voters! Secondly, all the red tones are really cool, but there''s almost a little bit too much of it. Taking the saturation down a tiny bit might help with that. <br/> <br/>I like the centered composition you used - usually I try to avoid centered compositions - but in my opinion, it worked well here! This is a cool idea for the challenge, it just needs a little technical work. Keep shooting! :)</td>', 'This looks like it would be really cool! I''m guessing that you are holding a flashlight with your hair over it? Well, here is my two cents. :) First of all, it''s out of focus. If you can fix that, and get a focused image, it will get you a much better photo, and thus a much better score with the voters! Secondly, all the red tones are really cool, but there''s almost a little bit too much of it. Taking the saturation down a tiny bit might help with that.  I like the centered composition you used - usually I try to avoid centered compositions - but in my opinion, it worked well here! This is a cool idea for the challenge, it just needs a little technical work. Keep shooting! :)', '2007-04-18 13:30:39.000000', NULL, 1),
(3559550, 499174, 62925, '<td valign="top">nice hairdo, personally i think the light is too strong on the hair and not enough on the face.</td>', 'nice hairdo, personally i think the light is too strong on the hair and not enough on the face.', '2007-04-18 13:30:44.000000', NULL, 1),
(3559551, 499323, 51538, '<td valign="top">Thanks for not being boring.... :)</td>', 'Thanks for not being boring.... :)', '2007-04-18 13:30:52.000000', NULL, 1),
(3559552, 498724, 57032, '<td valign="top">Great facial expression. A nice portrait overall, although the background is quite noisy.</td>', 'Great facial expression. A nice portrait overall, although the background is quite noisy.', '2007-04-18 13:31:00.000000', NULL, 1),
(3559553, 497305, 62925, '<td valign="top">thats an awesome face :)</td>', 'thats an awesome face :)', '2007-04-18 13:31:07.000000', NULL, 1),
