INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3559616, 498930, 63269, '<td valign="top">Cool! this has lots of potential, I think. It could use perhaps a little more contrast and... I don''t think it''s out of focus or blurry - it just could use a little more detail. I''ve found that by lowering my ISO I can usually get better detail. (even if it does make it so I have to brighten the photo up a little more.) Interesting shot though, I don''t think I''ve ever seen a hedgehog this close before! :)</td>', 'Cool! this has lots of potential, I think. It could use perhaps a little more contrast and... I don''t think it''s out of focus or blurry - it just could use a little more detail. I''ve found that by lowering my ISO I can usually get better detail. (even if it does make it so I have to brighten the photo up a little more.) Interesting shot though, I don''t think I''ve ever seen a hedgehog this close before! :)', '2007-04-18 13:39:30.000000', NULL, 1),
(3559619, 498819, 62925, '<td valign="top">ouch!</td>', 'ouch!', '2007-04-18 13:40:07.000000', NULL, 1),
(3559620, 497577, 5728, '<td valign="top">This will get you a top placing for sure..... the hair is almost almost almost on the verge of being oversharpened For some "yes" for some "no", for me you have pushed it to the top limit :)</td>', 'This will get you a top placing for sure..... the hair is almost almost almost on the verge of being oversharpened For some "yes" for some "no", for me you have pushed it to the top limit :)', '2007-04-18 13:40:16.000000', NULL, 1),
(3559622, 497686, 62925, '<td valign="top">ahh snakes!</td>', 'ahh snakes!', '2007-04-18 13:40:32.000000', NULL, 1),
(3559624, 498891, 5728, '<td valign="top">good!</td>', 'good!', '2007-04-18 13:40:37.000000', NULL, 1),
(3559626, 498652, 62925, '<td valign="top">seems very tricky.<br/> <br/>did you come up with an equation to grow your hair back? :P</td>', 'seems very tricky. did you come up with an equation to grow your hair back? :P', '2007-04-18 13:41:29.000000', NULL, 1),
(3559629, 499383, 58452, '<td valign="top">WTH???  LOL.  I like the colors and bokeh.  The exposure and lighting look pretty good....<br/>but WTH is it????  LOL</td>', 'WTH???  LOL.  I like the colors and bokeh.  The exposure and lighting look pretty good....but WTH is it????  LOL', '2007-04-18 13:42:10.000000', NULL, 1),
(3559631, 499097, 58452, '<td valign="top">My eyes look like that sometimes on Monday morning.  Nice capture.</td>', 'My eyes look like that sometimes on Monday morning.  Nice capture.', '2007-04-18 13:42:55.000000', NULL, 1),
(3559632, 497667, 5728, '<td valign="top">Technically very good, especially the toning. However I find the crossover between the two images too abrupt. I like where you are going here, but that hard line between the two with different sharpness values is a little off putting.... otherwise very cool!</td>', 'Technically very good, especially the toning. However I find the crossover between the two images too abrupt. I like where you are going here, but that hard line between the two with different sharpness values is a little off putting.... otherwise very cool!', '2007-04-18 13:43:12.000000', NULL, 1),
(3559633, 499365, 58452, '<td valign="top">Now, dem some dreads.....<br/>Very nice composition.</td>', 'Now, dem some dreads.....Very nice composition.', '2007-04-18 13:43:32.000000', NULL, 1),
(3559635, 498652, 5728, '<td valign="top">JÄGERMEISTER!!!!</td>', 'JÄGERMEISTER!!!!', '2007-04-18 13:43:46.000000', NULL, 1),
(3559638, 499135, 63269, '<td valign="top">hmmm... almost a little bit too much of the post-procesing for me, but I really do like it! Something you''ve captured with the highlights and shadows is absolutely beautifully breath-taking!!! The same thing with the border. I don''t really like it, but on the other hand I think it''s part of what makes the image so beautiful. <br/>Unfortunately, I''m guessing that this will score pretty bad with the voters. It seems like with really photoshopped images like this, they tend to just give it a bad vote and move on, without really stopping to look at it to see what the photographer was trying to get at. :( Hopefully I''m wrong though. An 8 from me. Good luck!</td>', 'hmmm... almost a little bit too much of the post-procesing for me, but I really do like it! Something you''ve captured with the highlights and shadows is absolutely beautifully breath-taking!!! The same thing with the border. I don''t really like it, but on the other hand I think it''s part of what makes the image so beautiful. Unfortunately, I''m guessing that this will score pretty bad with the voters. It seems like with really photoshopped images like this, they tend to just give it a bad vote and move on, without really stopping to look at it to see what the photographer was trying to get at. :( Hopefully I''m wrong though. An 8 from me. Good luck!', '2007-04-18 13:45:03.000000', NULL, 1),
(3559642, 497103, 58452, '<td valign="top">I would like this better if the camera were perpendicular to the  side of the subject. Would be nicer in a larger size.  We can use up to 640 on a side here.</td>', 'I would like this better if the camera were perpendicular to the  side of the subject. Would be nicer in a larger size.  We can use up to 640 on a side here.', '2007-04-18 13:46:26.000000', NULL, 1),
(3559645, 498634, 5728, '<td valign="top">Love this painting, very well done. Pity it won''t do so well on this "pure fanatical photography only" site :( The border is not really my cup of tea especially contrasting against the lighter luminance values at the top of the image. (8)....</td>', 'Love this painting, very well done. Pity it won''t do so well on this "pure fanatical photography only" site :( The border is not really my cup of tea especially contrasting against the lighter luminance values at the top of the image. (8)....', '2007-04-18 13:47:18.000000', NULL, 1),
(3559646, 498675, 63269, '<td valign="top">Cool! A very beautiful horse. Although technically wonderful, this photo looks like it could use a little something extra to make it more interesting. I''m almost tempted to say more contrast... but I''m not sure. Maybe some experimenting with burning and dodging in Photoshop might have been cool. It''s a really nice shot though!</td>', 'Cool! A very beautiful horse. Although technically wonderful, this photo looks like it could use a little something extra to make it more interesting. I''m almost tempted to say more contrast... but I''m not sure. Maybe some experimenting with burning and dodging in Photoshop might have been cool. It''s a really nice shot though!', '2007-04-18 13:47:27.000000', NULL, 1),
(3559647, 498973, 5728, '<td valign="top">Horosho, moladets!</td>', 'Horosho, moladets!', '2007-04-18 13:48:05.000000', NULL, 1),
(3559650, 497924, 63269, '<td valign="top">Lovely! Very nice... I love the subtlty of all the shadows, and I find it very interesting that there are really no highlights in this image. (usually I can''t stand that!) Great shot.</td>', 'Lovely! Very nice... I love the subtlty of all the shadows, and I find it very interesting that there are really no highlights in this image. (usually I can''t stand that!) Great shot.', '2007-04-18 13:48:43.000000', NULL, 1),
(3559651, 497348, 51538, '<td valign="top">Ambitious idea and pretty well executed too.  The mirror image is a tiny bit off...  Well done.</td>', 'Ambitious idea and pretty well executed too.  The mirror image is a tiny bit off...  Well done.', '2007-04-18 13:49:16.000000', NULL, 1),
(3559654, 499106, 63269, '<td valign="top">A cute shot! I might suggest bringing the contrast down a tiny bit though - things that are supposed to be just white on this photo are starting to get a little blown-out. But the shallow depth of field and the focus are great!</td>', 'A cute shot! I might suggest bringing the contrast down a tiny bit though - things that are supposed to be just white on this photo are starting to get a little blown-out. But the shallow depth of field and the focus are great!', '2007-04-18 13:50:15.000000', NULL, 1),
(3559658, 499091, 5728, '<td valign="top">Should do you well. especially with those eyes. I don''t like the way the hair is drowning into the darkness so much, I would have preferred to see a little more detail at the top of the upper girl''s hair. My wife is always getting at me about hair drowning out too much into darkness :)</td>', 'Should do you well. especially with those eyes. I don''t like the way the hair is drowning into the darkness so much, I would have preferred to see a little more detail at the top of the upper girl''s hair. My wife is always getting at me about hair drowning out too much into darkness :)', '2007-04-18 13:51:33.000000', NULL, 1),
(3559660, 498973, 25728, '<td valign="top">AMAZING use of the expert editing ruleset. This is stunning, well executed and brilliantly thought out. My choice for winner, and my highest mark, plus a favorite.</td>', 'AMAZING use of the expert editing ruleset. This is stunning, well executed and brilliantly thought out. My choice for winner, and my highest mark, plus a favorite.', '2007-04-18 13:51:54.000000', NULL, 1),
(3559662, 499229, 58452, '<td valign="top">Interesting.  Why are so many hair shots being dominated by beautiful eyes!  You could fall into those pupils.  I hope the subject didn''t shave the hair off for this shot.  But... I hope she''s not going through a bad illness.<br/>If she is... I hope she recovers soon.  I like the composition and the story it tells.  Congrats.</td>', 'Interesting.  Why are so many hair shots being dominated by beautiful eyes!  You could fall into those pupils.  I hope the subject didn''t shave the hair off for this shot.  But... I hope she''s not going through a bad illness.If she is... I hope she recovers soon.  I like the composition and the story it tells.  Congrats.', '2007-04-18 13:52:00.000000', NULL, 1),
(3559669, 497415, 5728, '<td valign="top">Very well done, cool idea, the tear makes this image. The sad thing is it won''t get you too far in the "hair" challenge. I like it.....</td>', 'Very well done, cool idea, the tear makes this image. The sad thing is it won''t get you too far in the "hair" challenge. I like it.....', '2007-04-18 13:53:50.000000', NULL, 1),
(3559675, 498117, 58452, '<td valign="top">I love the boldness of this image.  It makes the eye go back and forth across the frame.  I wish you''d made it diagonal across the frame.  With the cowlick almost where it is but the lollipop in the lower right.  Also the yellow back ground that is revealed jumps to the foreground of the image and is slightly distracting to me.  I still like this composition a lot.  Congrats.</td>', 'I love the boldness of this image.  It makes the eye go back and forth across the frame.  I wish you''d made it diagonal across the frame.  With the cowlick almost where it is but the lollipop in the lower right.  Also the yellow back ground that is revealed jumps to the foreground of the image and is slightly distracting to me.  I still like this composition a lot.  Congrats.', '2007-04-18 13:56:20.000000', NULL, 1),
(3559680, 498366, 63269, '<td valign="top">Nice colors and lighting - interesting idea, too.</td>', 'Nice colors and lighting - interesting idea, too.', '2007-04-18 13:58:34.000000', NULL, 1),
(3559682, 498916, 43774, '<td valign="top">I don''t like the hair coming out over the border, it has been cropped too jagged. But I do love the photo.</td>', 'I don''t like the hair coming out over the border, it has been cropped too jagged. But I do love the photo.', '2007-04-18 14:01:54.000000', NULL, 1),
(3559686, 499162, 63269, '<td valign="top">Now that is freaky! :) I immediately knew something was wrong, and then I slowly realized the head was on backwards! I love it! However, I think that a lot of the impact of this image is sort of lost by the grey border (at least for me). I would love to see what this would like like with a slightly smaller, black border, or simply no border at all. But it''s a very interesting, unusual, and creative image!</td>', 'Now that is freaky! :) I immediately knew something was wrong, and then I slowly realized the head was on backwards! I love it! However, I think that a lot of the impact of this image is sort of lost by the grey border (at least for me). I would love to see what this would like like with a slightly smaller, black border, or simply no border at all. But it''s a very interesting, unusual, and creative image!', '2007-04-18 14:02:28.000000', NULL, 1),
(3559688, 497306, 58452, '<td valign="top">Wow.  I can''t stop laughing when I see this one.  Beautiful tones and textures dangling in the black space.  PP doesn''t seem to distract in this case.  Best I''ve seen in the challenge so far, you really move the attention to the hair on the two heads.  I believe this one will top 10.  Congrats.</td>', 'Wow.  I can''t stop laughing when I see this one.  Beautiful tones and textures dangling in the black space.  PP doesn''t seem to distract in this case.  Best I''ve seen in the challenge so far, you really move the attention to the hair on the two heads.  I believe this one will top 10.  Congrats.', '2007-04-18 14:03:21.000000', NULL, 1),
(3559689, 496457, 63269, '<td valign="top">I looks like either this needs more contrast, or maybe the white-ballance was off. There really isn''t anything WHITE in this image - making it feel rather dull and unnatural. But I like the composition a lot... it''s very bold and creative! :)</td>', 'I looks like either this needs more contrast, or maybe the white-ballance was off. There really isn''t anything WHITE in this image - making it feel rather dull and unnatural. But I like the composition a lot... it''s very bold and creative! :)', '2007-04-18 14:03:33.000000', NULL, 1),
