INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3567487, 497900, 67180, '<td valign="top">Nice idea.  The surprise look best fits the first stroke of the brush which seems to have already occurred.  The results from the current stroke would be nearly invisible to the girl.  The left side seems only half restored w/ the wonder brush.  It seems odd she would have stopped half-way down and moved on.</td>', 'Nice idea.  The surprise look best fits the first stroke of the brush which seems to have already occurred.  The results from the current stroke would be nearly invisible to the girl.  The left side seems only half restored w/ the wonder brush.  It seems odd she would have stopped half-way down and moved on.', '2007-04-21 00:20:17.000000', NULL, 1),
(3567494, 499229, 67180, '<td valign="top">Might offer more with the model looking at the framed photo instead of directly at the camera.</td>', 'Might offer more with the model looking at the framed photo instead of directly at the camera.', '2007-04-21 00:23:01.000000', NULL, 1),
(3567509, 499174, 67180, '<td valign="top">The black lip color is too much for my taste.  It''s a big draw for the eye while adding nothing to the image other than shock value.</td>', 'The black lip color is too much for my taste.  It''s a big draw for the eye while adding nothing to the image other than shock value.', '2007-04-21 00:29:49.000000', NULL, 1),
(3567514, 498675, 68504, '<td valign="top">Powerful.  Good angle, good drape of hair (crimped or unbraided I wonder) falling to a point, lighting and framing.  (Can''t decide if background treetops add or subtract).  8</td>', 'Powerful.  Good angle, good drape of hair (crimped or unbraided I wonder) falling to a point, lighting and framing.  (Can''t decide if background treetops add or subtract).  8', '2007-04-21 00:31:23.000000', NULL, 1),
(3567521, 498698, 70484, '<td valign="top">I''m sorry, but I can''t tell what this is. I see stray strands of hair, but can''t make the rest out.</td>', 'I''m sorry, but I can''t tell what this is. I see stray strands of hair, but can''t make the rest out.', '2007-04-21 00:33:32.000000', NULL, 1),
(3567528, 498387, 70484, '<td valign="top">I love hairy cacti, but the busy background really seems to distract from the picture.</td>', 'I love hairy cacti, but the busy background really seems to distract from the picture.', '2007-04-21 00:36:15.000000', NULL, 1),
(3567542, 498819, 68504, '<td valign="top">Delightfully done. Like the bystanders. Title:  Not Rapunzel.</td>', 'Delightfully done. Like the bystanders. Title:  Not Rapunzel.', '2007-04-21 00:39:23.000000', NULL, 1),
(3567548, 498349, 68504, '<td valign="top">I keep wondering if all this wonderful water falling is really just coming from the hair.  Good lighting and colour.</td>', 'I keep wondering if all this wonderful water falling is really just coming from the hair.  Good lighting and colour.', '2007-04-21 00:42:25.000000', NULL, 1),
(3567567, 497993, 68504, '<td valign="top">Fascinating.  Love the buildings and the balding man double exposed on one of them.  Possibly too many people to carry the hair theme, though they fit the commuting idea.</td>', 'Fascinating.  Love the buildings and the balding man double exposed on one of them.  Possibly too many people to carry the hair theme, though they fit the commuting idea.', '2007-04-21 00:46:39.000000', NULL, 1),
