(3569777, 497675, 70181, '<td valign="top">Striking gaze.  I love the color in the eye.</td>', 'Striking gaze.  I love the color in the eye.', '2007-04-22 00:33:26.000000', NULL, 1),
(3569780, 497238, 70181, '<td valign="top">Great closeup.  A beautiful shot.</td>', 'Great closeup.  A beautiful shot.', '2007-04-22 00:34:07.000000', NULL, 1),
(3569781, 498916, 70181, '<td valign="top">Great idea.  Very creative.  Not sure I like the out of bounds look at the bottom though.</td>', 'Great idea.  Very creative.  Not sure I like the out of bounds look at the bottom though.', '2007-04-22 00:35:55.000000', NULL, 1),
(3569783, 497667, 7485, '<td valign="top">Highly original, and there''s a lot to like here. The stark lighting, green color-cast, high angle, and crouching model all work very well together to create a disturbed/troubled feel. But I don''t get the ropes in the foreground. They attract significant attention, but don''t really say anything to me. Also, the accidental alignment of the head in the lower panel and the shadow in the upper panel is distracting (would have been less distracting in a separated diptych). But all in all, impressive work!</td>', 'Highly original, and there''s a lot to like here. The stark lighting, green color-cast, high angle, and crouching model all work very well together to create a disturbed/troubled feel. But I don''t get the ropes in the foreground. They attract significant attention, but don''t really say anything to me. Also, the accidental alignment of the head in the lower panel and the shadow in the upper panel is distracting (would have been less distracting in a separated diptych). But all in all, impressive work!', '2007-04-22 00:36:57.000000', NULL, 1),
(3569784, 498138, 70181, '<td valign="top">Great action shot.  One of my favorites from the challenge.</td>', 'Great action shot.  One of my favorites from the challenge.', '2007-04-22 00:37:00.000000', NULL, 1),
(3569786, 499236, 70181, '<td valign="top">Too cute.  I love the expression.</td>', 'Too cute.  I love the expression.', '2007-04-22 00:37:10.000000', NULL, 1),
(3569792, 497675, 7485, '<td valign="top">Very well done! The subtle color in the iris is just right. I find the outline of the contact lens a bit distracting though, I would have edited that out.</td>', 'Very well done! The subtle color in the iris is just right. I find the outline of the contact lens a bit distracting though, I would have edited that out.', '2007-04-22 00:39:40.000000', NULL, 1),
(3569799, 496497, 7485, '<td valign="top">Beautiful model with excellent hair, but the background is distracting and her hair blends in too well with it. Also, why such a small image?</td>', 'Beautiful model with excellent hair, but the background is distracting and her hair blends in too well with it. Also, why such a small image?', '2007-04-22 00:46:59.000000', NULL, 1),
