(3579994, 498634, 53316, '<td valign="top">Wow, great score/placement and yay favorites! Congrats!!</td>', 'Wow, great score/placement and yay favorites! Congrats!!', '2007-04-25 03:00:26.000000', NULL, 0),
(3580001, 497675, 20330, '<td valign="top">thats a gorgeous eye there... amazing</td>', 'thats a gorgeous eye there... amazing', '2007-04-25 03:02:04.000000', NULL, 0),
(3580002, 498940, 53316, '<td valign="top">Yay shooting at arm''s length! I do that a lot. Didn''t get a chance to comment during, but I gave this an 8 because I really did like it a ton. High-contrast is cool, and the face isn''t in focus but the hair is more so, which makes the hair more of the point, which is neat.</td>', 'Yay shooting at arm''s length! I do that a lot. Didn''t get a chance to comment during, but I gave this an 8 because I really did like it a ton. High-contrast is cool, and the face isn''t in focus but the hair is more so, which makes the hair more of the point, which is neat.', '2007-04-25 03:02:11.000000', NULL, 0),
(3580003, 497337, 53316, '<td valign="top">Congrats on getting higher than you predicted! I thought this was a great shot.</td>', 'Congrats on getting higher than you predicted! I thought this was a great shot.', '2007-04-25 03:02:54.000000', NULL, 0),
(3580006, 498973, 22301, '<td valign="top">Its about time!!!! Big Congrats and glad to see your talent be rewarded with a ribbon. Maybe more people will discover your portfolio :)</td>', 'Its about time!!!! Big Congrats and glad to see your talent be rewarded with a ribbon. Maybe more people will discover your portfolio :)', '2007-04-25 03:03:20.000000', NULL, 0),
(3580009, 496980, 53316, '<td valign="top">I think if you''d smoothed out the skin 100% you might have gotten comments saying it looked too neat imaged. I love it as-is... actually really was impressed during voting by the texture of the skin. Looked very awesome to me.</td>', 'I think if you''d smoothed out the skin 100% you might have gotten comments saying it looked too neat imaged. I love it as-is... actually really was impressed during voting by the texture of the skin. Looked very awesome to me.', '2007-04-25 03:04:05.000000', NULL, 0),
