INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3587190, 498973, 53316, '<td valign="top">I think we all have things where we''re like "okay, how could this possibly ribbon?" and that just makes sense.  Most "digital art" stuff, even in expert, gets penalized, but silverfoxx just did a superb job at impacting us visually, and sometimes that trumps other things (i.e. stunning northern light shots winning over and over again even though people get tired of often-used themes, etc).  Unlike what Toyan said, I personally think that the 1s aren''t because of not liking her but instead just because of what you said, TooCool - this just does not appeal as "photography" to everyone.</td>', 'I think we all have things where we''re like "okay, how could this possibly ribbon?" and that just makes sense.  Most "digital art" stuff, even in expert, gets penalized, but silverfoxx just did a superb job at impacting us visually, and sometimes that trumps other things (i.e. stunning northern light shots winning over and over again even though people get tired of often-used themes, etc).  Unlike what Toyan said, I personally think that the 1s aren''t because of not liking her but instead just because of what you said, TooCool - this just does not appeal as "photography" to everyone.', '2007-04-27 01:06:31.000000', NULL, 0),
